});

test('mergeCustomers reassigns invoices from fromId to intoId', () => {
  const customers = listCustomers();
  const invoices = [
    { customerId: 'C-001', number: 'INV-1' },
    { customerId: 'C-002', number: 'INV-2' },
    { customerId: 'C-001', number: 'INV-3' },
  ];

  const result = mergeCustomers(customers, invoices, 'C-001', 'C-002');

  assert.equal(result.ok, true);
  const c001Invoices = result.value.invoices.filter((inv) => normalizeId(inv.customerId) === 'C-001');
  assert.equal(c001Invoices.length, 0);

  const c002Invoices = result.value.invoices.filter((inv) => normalizeId(inv.customerId) === 'C-002');
  assert.equal(c002Invoices.length, 3);
});

